import{_ as p}from"./chunks/image-011.CVj6F8GH.js";import{_ as a}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t}from"./chunks/image-012.nYG1NXV4.js";import{_ as o,o as s,c as r,a3 as n}from"./chunks/framework.DdpBa4_E.js";const l="/ReadBooks/assets/image-013.BPfXnU5v.gif",T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/33-论诽第二十四.md","filePath":"books/yan-tie-lun/33-论诽第二十四.md","lastUpdated":1784092560000}'),g={name:"books/yan-tie-lun/33-论诽第二十四.md"};function m(_,i,c,d,e,y){return s(),r("div",null,[...i[0]||(i[0]=[n('<p>论诽第二十四 【题解】</p><p>本篇就颜异、狄山反对汉武帝政策而展开辩论。丞相史批评颜异、狄山“处其位而非其朝，生乎世而讪其上，终以被戮而丧其躯”，将汉武帝杀颜异、狄山喻为帝尧“殛鲧放</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜”。文学认为，汉武帝时期由于贤良大臣不够齐备，才使张汤之类的奸臣得售其奸。因此君主治国，关键是得到舜、禹那样的贤臣辅佐。从史实来看，颜异只是认为汉武帝经济政策在施行过程中有不便之处，狄山只是主张与匈奴和亲，他们仅与皇帝政见不合，根本谈不上诽谤皇帝，可是他们却为此付出生命代价，专制螫毒如此惨烈，读之令人扼腕。</p><p>丞相史曰：“晏子有言：‘儒者华于言而寡于实[(1)]，繁于乐而舒于民[(2)]，久丧以害生[(3)]，厚葬以伤业[(4)]，礼烦而难行[(5)]，道迂而难遵[(6)]，称往古而訾当世[(7)]，贱所见而贵所闻。’此人本枉[(8)]，以己为式[(9)]。此颜异所以诛黜[(10)]，而狄山死于匈奴也[(11)]。处其位而非其朝[(12)]，生乎世而讪其上[(13)]，终以被戮而丧其躯，此独谁为负其累而蒙其殃乎？”</p><p>【注释】</p><p>[(1)]华于言：说得像一朵花。华，花。寡于实：很少结果。</p><p>[(2)]繁于乐：礼乐繁缛。舒于民：缓于治民。</p><p>[(3)]久丧：指儒家倡导的三年之丧。害生：祸害活人。</p><p>[(4)]厚葬：葬礼耗费巨大。伤业：伤害民生产业。</p><p>[(5)]礼烦：礼仪烦扰。《史记·孔子世家》载晏婴曰：“今孔子盛容饰，繁登降之礼，趋详之节，累世不能殚其学，当年不能究其礼。”</p><p>[(6)]道迂：道理迂腐。</p><p>[(7)]訾：诽谤。“訾”上原有“言”字，据王先谦、俞樾说校删。</p><p>[(8)]枉：曲。</p><p>[(9)]式：楷模。原作“拭”，据张敦仁说校改。</p><p>[(10)]颜异所以诛黜：《史记·平准书》载：“初，异为济南亭长，以廉直稍迁至九卿。上与张汤既造白鹿皮币，问异，异曰：‘今王侯朝贺以苍璧，直数千，而其皮荐反四十万，本末不相称。’天子不说。张汤又与异有郤，及人有告异以它议，事下张汤治异，异与客语，客语初令下有不便者，异不应，微反唇。汤奏异当，九卿见令不便，不入言而腹非，论死。”诛黜，诛杀。</p><p>[(11)]狄山死于匈奴：《史记·酷吏列传》载：“匈奴来请和亲，群臣议上前。博士狄山曰：‘和亲便。’上问其便，山曰：‘兵者凶器，未易数动。高帝欲伐匈奴，大困平城，乃遂结和亲。孝惠、高后时，天下安乐。及孝文帝欲事匈奴，北边萧然苦兵矣。孝景时，吴楚七国反，景帝往来两宫间，寒心者数月。吴楚已破，竟景帝不言兵，天下富实。今自陛下举兵击匈奴，中国以空虚，边民大困贫。由此观之，不如和亲。’上问汤，汤曰：‘此愚儒，无知。’狄山曰：‘臣固愚忠，若御史大夫汤乃诈忠。若汤之治淮南、江都，以深文痛诋诸侯，别疏骨肉，使蕃臣不自安。臣固知汤之为诈忠。’于是上作色曰：‘吾使生居一郡，能无使虏入盗乎？’曰：‘不能。’曰：‘居一县？’对曰：‘不能。’复曰：‘居一鄣间？’山自度辩穷且下吏，曰：‘能。’于是上遣山乘鄣。至月余，匈奴斩山头而去。”</p><p>[(12)]处其位：身居朝廷官位。非其朝：批评朝廷。</p><p>[(13)]生乎世：生于当世。讪其上：诽谤上司。《论语·阳货》：“恶居下流而讪上者。”</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>丞相史说：“晏婴说过：‘儒生说得像一朵花，却结不了果，繁于礼乐，缓于治民，长时间服丧，害苦活人，葬礼耗费太大，伤害民生产业，礼仪烦扰，难于施行，道理迂腐，难于遵守，称颂往古，诽谤当世，轻视所见的现实，重视传闻的上古。’这些人本身不正，却要以自己为楷模。这就是颜异被杀头，狄山死于匈奴的原因啊。居于朝廷官位，却要诽谤朝廷，生乎当世，却要批评上司，最终被杀，丧失性命，这又是为谁承担罪过、蒙受祸殃呢？”</p><p>文学曰：“礼所以防淫[(1)]，乐所以移风[(2)]，礼兴乐正则刑罚中。故堤防成而民无水灾，礼义立而民无乱患[(3)]。故礼义坏，堤防决，所以治者[(4)]，未之有也。孔子曰：‘礼与其奢也宁俭，丧与其易也宁戚。’[(5)]故礼之所为作，非以害生伤业也，威仪节文[(6)]，非以乱化伤俗也。治国谨其礼[(7)]，危国谨其法。昔秦以武力吞天下，而斯、高以妖孽累其祸[(8)]，废古术，隳旧礼，专任刑法，而儒、墨既丧焉。塞士之涂[(9)]，壅人之口，道谀日进而上不闻其过，此秦所以失天下而殒社稷也。故圣人为政，必先诛之，伪巧言以辅非而倾覆国家也[(10)]。今子安取亡国之语而来乎？夫公卿处其位，不正其道，而以意阿邑顺风[(11)]，疾小人浅浅面从[(12)]，以成人之过也。故知言之死[(13)]，不忍从苟合之徒，是以不免于缧绁[(14)]。悲夫！”</p><p>【注释】</p><p>[(1)]礼所以防淫：是说礼因性情而为之节文，不偏不倚地表达思想感情，是礼的宗旨，过与不及，都与礼相违。淫，过分。</p><p>[(2)]移风：移风易俗。</p><p>[(3)]礼义立而民无乱患：“而”字原无，据王利器说校补。</p><p>[(4)]所以：可以（用王利器说）。</p><p>[(5)]礼与其奢也宁俭，丧与其易也宁戚：见于《论语·八佾》。奢，奢侈。俭，俭朴。丧，丧礼。易，礼文周到（用杨伯峻说）。戚，过度悲哀。</p><p>[(6)]威仪：礼仪。节文：有节制的文饰。</p><p>[(7)]谨：重视。</p><p>[(8)]斯：李斯。高：赵高。以妖孽累其祸：因邪恶招来灾祸。</p><p>[(9)]涂：同“途”，晋升道路。</p><p>[(10)]伪：一本作“为”。辅非：助长错误。</p><p>[(11)]阿邑：曲从君主之意。邑，原作“色”，据王利器说校改。顺风：见风使舵。</p><p>[(12)]浅浅：通“</p><p><img src="'+t+'" alt="" loading="lazy"></p><p><img src="'+t+'" alt="" loading="lazy"></p><p>”，巧言。</p><p>[(13)]知言之死：知言之必死。</p><p>[(14)]缧绁（léi xiè）：捆绑犯人的绳索。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“礼用来防止过分，乐用来移风易俗，礼制兴盛，音乐纯正，就会刑罚适中。因而堤防修成之后民众就没有水灾，礼义确立之后民众就没有动乱祸患。因此礼义败坏，堤防溃决，可以治理的情形，从来没有。孔子说：‘礼，与其奢侈，宁愿俭朴；丧礼，与其礼文周到，宁可过度悲哀。’因而礼制作的本意，并不是要妨害活人、伤害民生产业的，礼仪只是有节制的文饰，并不是伤风败俗。治理的国家重视礼，危险的国家重视法。从前秦王朝以武力吞并天下，而李斯、赵高因邪恶招来灾祸，废除古代道术，毁坏旧的礼仪，专门依靠刑法，而儒、墨之道已经丧失殆尽了。堵塞士人进身道路，堵住民众的嘴巴，说奉承话的人步步高升，皇上听不见过错，这就是秦王朝失去天下、毁灭社稷的原因啊。因此圣人执政，一定要先杀掉像李斯、赵高这样的小人，因为他们用花言巧语来助长君主的错误，导致国家的颠覆。现在你怎么拿这些亡国之语来说呢？公卿处于重要地位，不能端正道路航向，而是刻意曲从，见风使舵，可恨小人巧言顺从，以致酿成别人过失。因此明知说了必死，也不忍心顺从苟合之徒，所以不免于牢狱之灾。可悲啊！”</p><p>丞相史曰：“檀柘而有乡[(1)]，萑苇而有藂[(2)]，言物类之相从也。孔子曰：‘德不孤，必有邻。’[(3)]故汤兴而伊尹至[(4)]，不仁者远矣[(5)]。未有明君在上而乱臣在下也。今先帝躬行仁圣之道[(6)]，以临海内[(7)]，招举俊才贤良之士，唯仁是用，诛逐乱臣，不避所亲，务以求贤而简退不肖[(8)]，犹尧之举舜、禹之族，殛鲧放</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>兜也[(9)]。而曰‘苟合之徒’，是则主非而臣阿[(10)]，是也？”</p><p>【注释】</p><p>[(1)]檀柘：两种贵重木材。有乡：有相同的生长土壤。</p><p>[(2)]萑（huán）苇：芦苇。藂（cónɡ）：聚集，丛生。</p><p>[(3)]德不孤，必有邻：见于《论语·里仁》。</p><p>[(4)]汤：商朝开国君主。伊尹：商汤贤相。关于商汤、伊尹遇合故事，司马迁在《史记·殷本纪》中有记载。</p><p>[(5)]不仁者远矣：见于《论语·阳渊》：“汤有天下，选于众，举伊尹，不仁者远矣。”</p><p>[(6)]先帝：指汉武帝。</p><p>[(7)]临：统治。</p><p>[(8)]简退：黜退。简，挑选。</p><p>[(9)]犹尧之举舜、禹之族，殛鲧（jí）放</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>（huān）兜也：尧举舜，见于《尚书·尧典》。举禹、殛鲧、放</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜，均为舜的举措。</p><p>[(10)]臣阿：臣子阿谀。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>丞相史说：“檀树、柘树有相同的生长土壤，萑苇、芦苇彼此聚生一处，这说明事物都是以类相从。孔子说：‘有道德的人不会孤独，一定会有人与他为邻。’因此商汤兴起，伊尹便来到他的身边，不仁的人就远远地走开了。从来没有圣明君主在上而乱臣在下的情形。如今已故武帝亲身施行仁圣之道，统治天下，招纳、举荐优秀人才和贤良之士，只任用仁人，诛杀驱逐那些犯上作乱之臣，不避皇亲国戚，务必求得贤才，黜退不肖之人，如同尧举荐舜、禹之辈，诛鲧，流放</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜一样。你们却说‘苟合之徒’，这就是说君主有错而臣子阿谀奉承，对吗？”</p><p>文学曰：“皋陶对舜：‘在知人，惟帝其难之。’[(1)]洪水之灾，尧独愁悴而不能治[(2)]，得舜、禹而九州宁。故虽有尧明之君[(3)]，而无舜、禹之佐，则纯德不流[(4)]。《春秋》刺有君而无主[(5)]。先帝之时，良臣未备，故邪臣得间[(6)]。尧得舜、禹而鲧殛</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>兜诛，赵简子得叔向而盛青肩诎[(7)]。语曰：‘未见君子，不知伪臣[(8)]。’《诗》云：‘未见君子，忧心忡忡。既见君子，我心则降。’[(9)]此之谓也。”</p><p>【注释】</p><p>[(1)]在知人，惟帝其难之：《尚书·皋陶谟》：“皋陶曰：‘都！在知人，在安民。’禹曰：‘吁！咸若时，惟帝其难之。’”丞相史以为是皋陶应对舜，属于记忆错误。知人，识别人才。帝，帝舜。难之，难于做到。</p><p>[(2)]愁悴：忧愁憔悴。</p><p>[(3)]尧明之君：一本作“尧之明君”。</p><p>[(4)]纯德：纯正美德。</p><p>[(5)]《春秋》刺有君而无主：《春秋公羊传·僖公二十二年》载：“宋公与楚人期战于泓之阳……已陈，然后襄公鼓之，宋师大败。故君子大其不鼓不成列，临大事而不忘大礼，有君而无臣。”据此，此句当为“《春秋》刺有君而无臣”。有君而无臣，有贤君而无贤臣。</p><p>[(6)]得间：得以钻空子。</p><p>[(7)]赵简子得叔向而盛青肩诎（chù）：赵简子，春秋后期晋国正卿。叔向，春秋后期晋国贤大夫，主要活动在晋悼公、晋平公、晋昭公时期。盛青肩，晋国奸臣。诎，贬黜。</p><p>[(8)]伪臣：奸臣。</p><p>[(9)]未见君子，忧心忡忡。既见君子，我心则降：见于《诗经·召南·草虫》和《小雅·出车》。降，平静下来。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“皋陶应对帝舜说：‘在识别人才方面，即使是帝舜也难以做到。’洪水酿成大灾，帝尧忧愁憔悴而不能治理，在得到舜和禹以后才使九州安宁。因此即使有帝尧那样的英明君主，如果没有舜和禹的辅佐，那么帝尧的纯正美德就不能流芳千古。《春秋》讥刺有明君而无贤臣。已故武帝时期，贤良大臣不够齐备，因此才使奸臣钻了空子。帝尧得到舜和禹而鲧和</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜被杀，赵简子得到贤臣叔向而盛青肩被废黜。俗语说：‘没有看到君子，就不知道何为奸臣。’《诗经·小雅·出车》说：‘未见君子，忧心忡忡。已见君子，我心平静。’说的就是这种情形啊。”</p><p>丞相史曰：“尧任鲧、</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>兜，得舜、禹而放殛之以其罪，而天下咸服，诛不仁也[(1)]。人君用之齐民[(2)]，而颜异，济南亭长也[(3)]，先帝举而加之高位，官至上卿[(4)]。狄山起布衣，为汉议臣，处舜、禹之位，执天下之中，不能以治，而反坐讪上[(5)]；故</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>兜之诛加而刑戮至焉。贤者受赏而不肖者被刑，固其然也。文学又何怪焉？”</p><p>【注释】</p><p>[(1)]尧任鲧、</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜，得舜、禹而放殛之以其罪，而天下咸服，诛不仁也：《孟子·万章上》：“舜流共工于幽州，放</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜于崇山，杀三苗于三危，殛鲧于羽山，四罪而天下咸服，诛不仁也。”</p><p>[(2)]齐民：治民。</p><p>[(3)]亭：汉代十里一亭。</p><p>[(4)]上卿：颜异任大农，为九卿之一。</p><p>[(5)]坐：因……犯罪。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>丞相史说：“帝尧先任用鲧和</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜，得到舜和禹之后，便根据他们的罪行诛杀鲧，流放</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜，天下人都心悦诚服，因为这是诛杀不仁的人。君主用举贤除奸的方法治理民众。颜异最初只是济南的一位亭长，已故武帝提拔他，让他担任高官，官职达到上卿。狄山起身于一介布衣，为汉朝议事之臣。他们都处于当年舜和禹的位置之上，执掌天下议论的正确标准，可是他们不能辅佐皇上治民，反而犯了诽谤皇上的大罪；因而他们才受到类似于</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>兜那样的处罚，遭到杀头。贤者受奖赏，不贤者受刑罚，本来就应该如此，你们文学又有什么可奇怪的呢？”</p><p>文学曰：“论者相扶以义[(1)]，相喻以道[(2)]，从善不求胜，服义不耻穷[(3)]。若相迷以伪[(4)]，相乱以辞，相矜于后息[(5)]，期于苟胜[(6)]，非其贵者也。夫苏秦、张仪，荧惑诸侯[(7)]，倾覆万乘[(8)]，使人失其所恃[(9)]；非不辩[(10)]，然乱之道也。君子疾鄙夫之不可与事君[(11)]，患其听从而无所不至也[(12)]。今子不听正义以辅卿相，又从而顺之，好须臾之说[(13)]，不计其后。若子之为人吏[(14)]，宜受上戮[(15)]，子姑默矣！”</p><p>【注释】</p><p>[(1)]相扶以义：以大义相会，即以义会友。</p><p>[(2)]喻：晓喻。</p><p>[(3)]穷：受窘。</p><p>[(4)]伪：歪理邪说。</p><p>[(5)]矜：夸耀。后息：辩论双方，你来我往，以最后停息者为胜。此处以“后息”指在辩论中最后取胜。</p><p>[(6)]期：希望。苟胜：用不正当的方法取胜。</p><p>[(7)]荧惑：迷惑。《史记·张仪列传》：“苏秦荧惑诸侯，以是为非，以非为是。”</p><p>[(8)]倾覆：颠覆。万乘：拥有万辆兵车的大国。</p><p>[(9)]失其所恃：失去原来依靠，指放弃原来立场。</p><p>[(10)]辩：雄辩，善辩。</p><p>[(11)]疾：痛恨。鄙夫：卑鄙小人。与：共同，一起。《论语·阳货》：“鄙夫可与事君也与哉？”</p><p>[(12)]听从而无所不至：表面上对君主言听计从，背后无所不为。</p><p>[(13)]须臾之说：片刻有利的言论。须臾，片刻。</p><p>[(14)]为人吏：做他人的属官。</p><p>[(15)]上戮：最重的处罚。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“在一起讨论的人应该以大义相会，以大道相晓喻，从善如流，不求个人取胜，服从大义，不耻受窘。如果以歪理邪说相迷惑，以言辞相扰乱，彼此以最后取胜相夸耀，希望以不正当的方法取胜，这种行为并不可贵。战国纵横家苏秦、张仪，迷惑诸侯，颠覆万乘诸侯国，使人们放弃原来的立场；不能说他们不雄辩，然而他们那一套是致乱之道。君子痛恨这种卑鄙小人，不能与他们一起事奉君主，怕他们表面上对君主言听计从，而背后却无所不为。如今你不听取正义的意见来辅佐卿相，反而曲意顺承上司，喜好片刻有利的言论，完全不考虑它的后果。像你这样的人做属官，应该接受最重的刑罚。你姑且闭嘴吧！”</p><p>丞相史曰：“盖闻士之居世也，衣服足以胜身[(1)]，食饮足以供亲[(2)]，内足以相恤[(3)]，外不求于人。故身修然后可以理家，家理然后可以治官[(4)]。故饭蔬粝者不可以言孝[(5)]，妻子饥寒者不可以言慈，绪业不修者不可以言理[(6)]。居斯世，行斯身[(7)]，而有此三累者[(8)]，斯亦足以默矣。”</p><p>【注释】</p><p>[(1)]胜身：御寒保身。</p><p>[(2)]供亲：供养父母双亲。</p><p>[(3)]相恤：指一家互相体恤。</p><p>[(4)]治官：治理官府公事。《孝经》：“居家理故治可移于官。”</p><p>[(5)]饭：用做动词，吃。粝：粗粮。</p><p>[(6)]绪业：事业，遗业。修：原作“备”，据陈遵默说校改。</p><p>[(7)]行斯身：行事立身。</p><p>[(8)]三累：饭蔬粝、妻子饥寒、绪业不修。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>【译文】</p><p>丞相史说：“我听说士人生活在世上，衣服足可以御寒保身，饮食足可以供奉双亲，对内家人足可以相互体恤，对外不求于他人。因此自身修养完成之后可以治理家族，家族得到治理之后可以治理官府公事。因而给父母吃蔬菜粗粮的人不可以说他是孝子，妻子儿女挨饥受寒的人不可以说他慈爱，祖辈遗业没有继承好的人不可以说善于治理家族。生在当世，行事立身，而有给父母吃蔬菜粗粮、妻子儿女挨饥受寒、祖辈遗业没有继承好这三项拖累，那也足可以闭嘴了。”</p>',142)])])}const h=o(g,[["render",m]]);export{T as __pageData,h as default};
